import{_ as e,o as t,c as i,a2 as s}from"./chunks/framework.CyZTVJbV.js";const k=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"ja/faq.md","filePath":"ja/faq.md"}'),o={name:"ja/faq.md"};function l(n,a,r,d,p,c){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><blockquote><p><a href="./../en/faq">🇬🇧 English</a> • <a href="./faq">🇯🇵 日本語</a></p></blockquote><h2 id="q1-なぜ-synpress-や-metamask-test-dapp-ではなく-kiwa-なのか" tabindex="-1">Q1: なぜ Synpress や MetaMask Test Dapp ではなく kiwa なのか <a class="header-anchor" href="#q1-なぜ-synpress-や-metamask-test-dapp-ではなく-kiwa-なのか" aria-label="Permalink to &quot;Q1: なぜ Synpress や MetaMask Test Dapp ではなく kiwa なのか&quot;">​</a></h2><p>A: 既存ツールは MetaMask 拡張機能を経由する E2E が多く、CI で wallet popup の UI 操作を再現するため flaky になりがちです。 kiwa は wallet を <strong>コード内で完結</strong> させ、popup / approve UI を再現せず CI 安定性を最優先にします。 比較は <a href="./../COMPARISON">docs/COMPARISON.md</a> を参照してください。</p><h2 id="q2-anvil-が起動しない-anvil-not-found-in-path" tabindex="-1">Q2: anvil が起動しない (<code>anvil not found in PATH</code>) <a class="header-anchor" href="#q2-anvil-が起動しない-anvil-not-found-in-path" aria-label="Permalink to &quot;Q2: anvil が起動しない (`anvil not found in PATH`)&quot;">​</a></h2><p>A: Foundry をインストールして PATH に通してください。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://foundry.paradigm.xyz</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">foundryup</span></span></code></pre></div><h2 id="q3-port-8545-が既に使われている" tabindex="-1">Q3: port 8545 が既に使われている <a class="header-anchor" href="#q3-port-8545-が既に使われている" aria-label="Permalink to &quot;Q3: port 8545 が既に使われている&quot;">​</a></h2><p>A: 別 anvil プロセスが起動している可能性。kill するか別 port を <code>startAnvil({ port: 8546 })</code> で指定してください。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsof</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -iTCP:8545</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sTCP:LISTEN</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">kill</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="q4-test-が-stake-balance-loading-で-fail-する" tabindex="-1">Q4: test が stake-balance: (loading) で fail する <a class="header-anchor" href="#q4-test-が-stake-balance-loading-で-fail-する" aria-label="Permalink to &quot;Q4: test が stake-balance: (loading) で fail する&quot;">​</a></h2><p>A: <code>.env.local</code> の contract address が build 時に baked-in されていない可能性。 Next.js は build 時に <code>.env.local</code> を inline するため、global-setup で書いた address が次の build まで反映されません。 <code>pretest</code> で <code>.env.local</code> を書く / build キャッシュをクリアする (<code>rm -rf .next</code>) のいずれかが必要です。</p><h2 id="q5-複数-example-で-port-が衝突する" tabindex="-1">Q5: 複数 example で port が衝突する <a class="header-anchor" href="#q5-複数-example-で-port-が衝突する" aria-label="Permalink to &quot;Q5: 複数 example で port が衝突する&quot;">​</a></h2><p>A: 各 example で固有 port を使う (3033-3047)。詳細は <code>examples/*/package.json</code> の <code>scripts.dev</code> / <code>start</code> 参照。 anvil は default 8545 共有のため、複数 example の並列実行は不可。</p><h2 id="q6-wagmi-v2-rainbowkit-v2-ではなく-connectkit-reown-を使いたい" tabindex="-1">Q6: wagmi v2 / RainbowKit v2 ではなく ConnectKit / Reown を使いたい <a class="header-anchor" href="#q6-wagmi-v2-rainbowkit-v2-ではなく-connectkit-reown-を使いたい" aria-label="Permalink to &quot;Q6: wagmi v2 / RainbowKit v2 ではなく ConnectKit / Reown を使いたい&quot;">​</a></h2><p>A: kiwa は EIP-1193 / EIP-6963 標準に準拠しているため、いずれの wallet picker でも動作します。 特定 picker の test 対応は <code>examples/basic-connect/tests/eip6963.spec.ts</code> を参考にしてください。</p><h2 id="q7-contract-deploy-が遅い" tabindex="-1">Q7: contract deploy が遅い <a class="header-anchor" href="#q7-contract-deploy-が遅い" aria-label="Permalink to &quot;Q7: contract deploy が遅い&quot;">​</a></h2><p>A: anvil の deterministic deploy は固定 deployer + 連続 nonce で動くため、毎回同じ address が得られます。 deploy artifact (<code>forge-out/</code>) を repo に commit すると <code>forge build</code> を skip できて高速化します。</p><h2 id="q8-時間に依存する-test-の書き方は" tabindex="-1">Q8: 時間に依存する test の書き方は <a class="header-anchor" href="#q8-時間に依存する-test-の書き方は" aria-label="Permalink to &quot;Q8: 時間に依存する test の書き方は&quot;">​</a></h2><p>A: anvil RPC の <code>evm_snapshot</code> / <code>evm_revert</code> / <code>evm_increaseTime</code> を活用してください。 詳細は <a href="./cookbook/time-manipulation">Cookbook: 時間操作で test する</a>。</p><h2 id="q9-test-がランダムに-fail-する-flaky" tabindex="-1">Q9: test がランダムに fail する (flaky) <a class="header-anchor" href="#q9-test-がランダムに-fail-する-flaky" aria-label="Permalink to &quot;Q9: test がランダムに fail する (flaky)&quot;">​</a></h2><p>A: 以下を順番に確認してください。</p><ol><li>前回 run の anvil が残っていないか (<code>lsof -iTCP:8545</code>)</li><li><code>.env.local</code> が古い contract address を持っていないか</li><li>polling-based assertion が <code>waitForChainState</code> で deterministic 化できないか</li></ol><h2 id="q10-公式サポート範囲" tabindex="-1">Q10: 公式サポート範囲 <a class="header-anchor" href="#q10-公式サポート範囲" aria-label="Permalink to &quot;Q10: 公式サポート範囲&quot;">​</a></h2><p>A: kiwa は Headless Chromium + 標準 wallet API のみサポートします。 ブラウザ拡張 (MetaMask 等の) UI 操作、Firefox / Safari、mobile WebView は非対応です。</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="https://github.com/cardene777/kiwa/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li><li><a href="./concepts/README">Concepts</a></li><li><a href="./cookbook/README">Cookbook</a></li></ul>',27)])])}const u=e(o,[["render",l]]);export{k as __pageData,u as default};
